  aofRemoveTempFile(server.child_pid);
  /* Clear AOF buffer and delete temp incr aof for next rewrite. */
  if (server.aof_state == AOF_WAIT_REWRITE) {
    sdsfree(server.aof_buf);
    server.aof_buf = sdsempty();
    aofDelTempIncrAofFile();
